mapper.select:
SELECT
    m.*
FROM qms.material_inspection m
WHERE m.is_deleted = 0
  AND m.plant_code = #{plantCode}
  AND m.inspection_result = #{inspectionResult}
  AND m.created_at >= #{startAt}
  AND m.created_at <= #{endAt}
  AND NOT EXISTS (
      SELECT 1 FROM qms.exception_order e
      WHERE e.is_deleted = 0
        AND e.source_type = #{sourceType}
        AND e.source_id = m.id
  )
ORDER BY m.created_at DESC

SELECT COUNT(*)
FROM qms.material_inspection
WHERE is_deleted = 0
  AND plant_code = #{plantCode}
  AND supplier_code = #{supplierCode}
  AND material_code = #{materialCode}
  AND inspection_result = '不合格'
  AND inspection_date >= #{startDate}
  AND inspection_date <= #{endDate}
